import * as React from 'react';
import { describe, it, expect, vi, afterEach } from 'vitest';
import { render, screen, fireEvent, cleanup, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

afterEach(cleanup);

describe('probe: Field.Control controlled sync', () => {
  it('A: server error set together with a programmatic value reset is wiped', async () => {
    function App() {
      const [password, setPassword] = React.useState('secret');
      const [errors, setErrors] = React.useState<Record<string, string> | undefined>(undefined);
      return (
        <Form
          errors={errors}
          onClearErrors={setErrors}
          onFormSubmit={() => {
            // Login failed: show the server error and clear the password, in one update.
            setErrors({ password: 'Incorrect password' });
            setPassword('');
          }}
        >
          <Field.Root name="password" data-testid="root">
            <Field.Control value={password} onValueChange={setPassword} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="submit">submit</button>
        </Form>
      );
    }

    render(<App />);
    fireEvent.submit(screen.getByRole('button').closest('form')!);
    await act(async () => {});

    expect((screen.getByRole('textbox') as HTMLInputElement).value).toBe('');
    // Under the PR this fails: the error is cleared by the value sync.
    expect(screen.queryByTestId('error')?.textContent ?? '(no error)').toBe('Incorrect password');
  });

  it('B: submit-time validate receives a string for numeric controlled value', async () => {
    const seen: unknown[] = [];
    function App() {
      const [value, setValue] = React.useState(5);
      return (
        <Form>
          <Field.Root name="n" validate={(v) => { seen.push(v); return null; }}>
            <Field.Control value={value} onValueChange={(v) => setValue(Number(v))} />
          </Field.Root>
          <button type="submit">submit</button>
        </Form>
      );
    }
    render(<App />);
    fireEvent.submit(screen.getByRole('button').closest('form')!);
    await act(async () => {});
    expect(seen).toEqual([5]);
  });

  it('C: controlled value change while disabled still validates and clears errors', async () => {
    const validate = vi.fn(() => 'bad');
    function App() {
      const [value, setValue] = React.useState('a');
      return (
        <Field.Root name="x" validationMode="onChange" validate={validate} disabled>
          <Field.Control value={value} onValueChange={setValue} />
          <button type="button" onClick={() => setValue('b')}>set</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByRole('button'));
    await act(async () => {});
    expect(validate).toHaveBeenCalledTimes(0);
  });

  it('D: render count per keystroke, controlled + validationMode=onChange', async () => {
    const renders = { current: 0 };
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={() => null}>
          <Field.Control
            data-testid="c"
            value={value}
            onValueChange={setValue}
            render={(props) => {
              renders.current += 1;
              return <input {...props} />;
            }}
          />
        </Field.Root>
      );
    }
    render(<App />);
    const c = screen.getByTestId('c');
    fireEvent.change(c, { target: { value: 'a' } });
    await act(async () => {});
    const settled = renders.current;
    fireEvent.change(c, { target: { value: 'ab' } });
    await act(async () => {});
    fireEvent.change(c, { target: { value: 'abc' } });
    await act(async () => {});
    // eslint-disable-next-line no-console
    console.log('renders per keystroke (controlled, onChange mode):', (renders.current - settled) / 2);
    expect(true).toBe(true);
  });

  it('E: uncontrolled cancel still flips dirty/filled', async () => {
    render(
      <Field.Root data-testid="root">
        <Field.Control onValueChange={(_v, d) => d.cancel()} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const root = screen.getByTestId('root');
    // eslint-disable-next-line no-console
    console.log('dirty after cancel:', root.hasAttribute('data-dirty'), 'filled:', root.hasAttribute('data-filled'));
    expect(true).toBe(true);
  });

  it('F: data-focused latch on disable while focused (claimed fix in PR body)', async () => {
    function App() {
      const [disabled, setDisabled] = React.useState(false);
      return (
        <Field.Root data-testid="root">
          <Field.Control disabled={disabled} />
          <button type="button" onClick={() => setDisabled(true)}>disable</button>
        </Field.Root>
      );
    }
    render(<App />);
    const input = screen.getByRole('textbox');
    act(() => input.focus());
    fireEvent.focus(input);
    expect(screen.getByTestId('root')).toHaveAttribute('data-focused', '');
    fireEvent.click(screen.getByRole('button'));
    await act(async () => {});
    // eslint-disable-next-line no-console
    console.log('focused after disable:', screen.getByTestId('root').hasAttribute('data-focused'));
    expect(true).toBe(true);
  });

  it('G: value={null} transition does not sync', async () => {
    function App() {
      const [value, setValue] = React.useState<string | null>('abc');
      return (
        <Field.Root data-testid="root">
          <Field.Control value={value as any} onValueChange={setValue} />
          <button type="button" onClick={() => setValue(null)}>null</button>
        </Field.Root>
      );
    }
    const spy = vi.spyOn(console, 'error').mockImplementation(() => {});
    render(<App />);
    expect(screen.getByTestId('root')).toHaveAttribute('data-filled', '');
    fireEvent.click(screen.getByRole('button'));
    await act(async () => {});
    // eslint-disable-next-line no-console
    console.log('filled after null:', screen.getByTestId('root').hasAttribute('data-filled'), 'dom:', JSON.stringify((screen.getByRole('textbox') as HTMLInputElement).value));
    spy.mockRestore();
    expect(true).toBe(true);
  });

  it('H: onChange handler (not onValueChange) controlled still syncs validation', async () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={validate} data-testid="root">
          <Field.Control value={value} onChange={(e) => setValue(e.target.value)} />
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    await act(async () => {});
    expect(validate).toHaveBeenCalledTimes(1);
    expect(screen.getByTestId('root')).toHaveAttribute('data-dirty', '');
  });
});

